package com.example.checkboxradiobutton; import android.os.Bundle; import android.view.View; import android.widget.CheckBox; import android.widget.RadioButton; import android.widget.RadioGroup; import android.widget.TextView; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { RadioGroup rgGender; CheckBox cbReading,cbTravel,cbMovies; TextView tvSelectedGender,tvSelectedHobbies; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);rgGender=findViewById(R.id.rgGender);cbReading=findViewById(R.id.cbReading);cbTravel=findViewById(R.id.cbTravel);cbMovies=findViewById(R.id.cbMovies);tvSelectedGender=findViewById(R.id.tvSelectedGender);tvSelectedHobbies=findViewById(R.id.tvSelectedHobbies);} public void displaySelection(View v){int id=rgGender.getCheckedRadioButtonId();if(id==-1){Toast.makeText(this,"Please select a gender",Toast.LENGTH_SHORT).show();return;}RadioButton r=findViewById(id);StringBuilder h=new StringBuilder();if(cbReading.isChecked())h.append("Reading");if(cbTravel.isChecked()){if(h.length()>0)h.append(", ");h.append("Travelling");}if(cbMovies.isChecked()){if(h.length()>0)h.append(", ");h.append("Watching Movies");}if(h.length()==0)h.append("None");tvSelectedGender.setText("Gender: "+r.getText());tvSelectedHobbies.setText("Hobbies: "+h);}}
